// spec: specs/location-map.md 3.3 · кейс .qa/tests/location-map/MAP-03.md
// free один в пустом месте (эмуляция: Негев, 30.61/34.80). Шаринг включается → @data, в конце выключается.
import { test, expect } from '@playwright/test';
import path from 'path';
import { enableSharing, disableSharing } from './map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 30.61, longitude: 34.8, accuracy: 10 },
  permissions: ['geolocation'],
});

const EMPTY = 'אין כרגע אנשים בקרבתך';

test.describe('מסך מפת זמן אמת — состояния', () => {
  test('пусто — «אין כרגע אנשים בקרבתך»; загрузка и ошибка — без заголовка пустого состояния @iphone @data (#0f19c0)', async ({ page }) => {
    try {
      await enableSharing(page);
      // Пусто (AC 3): заголовок и пояснение.
      await page.reload();
      await expect(page.getByText(EMPTY)).toBeVisible();
      await expect(page.getByText('אין כרגע אנשים רלוונטיים בסביבה')).toBeVisible();

      // Загрузка (AC 4; Р2): ответ задерживается — индикатор «טוען…», заголовка пустого состояния нет.
      let release!: () => void;
      const gate = new Promise<void>((r) => (release = r));
      await page.route('**/rpc/nearby_live', async (route) => { await gate; await route.continue().catch(() => {}); });
      await page.reload();
      await expect(page.getByRole('progressbar', { name: 'טוען…' })).toBeVisible();
      await expect(page.getByText('מחפשים מי בסביבה…')).toBeVisible();
      await expect(page.getByText(EMPTY)).toHaveCount(0);
      release();
      await page.unroute('**/rpc/nearby_live');

      // Ошибка сети (Р2): заголовка пустого состояния нет.
      await page.route('**/rpc/nearby_live', (route) => route.abort());
      const failed = page.waitForEvent('requestfailed', (r) => r.url().includes('/rpc/nearby_live'));
      await page.reload();
      await failed;
      await expect(page.getByText('אני', { exact: true })).toBeVisible();
      await expect(page.getByText('מחפשים מי בסביבה…')).toBeVisible();
      await expect(page.getByText(EMPTY)).toHaveCount(0);
      await page.unroute('**/rpc/nearby_live');
    } finally {
      await page.unrouteAll({ behavior: 'ignoreErrors' }).catch(() => {});
      await disableSharing(page).catch(() => {});
      await saveSession(page, 'free');
    }
  });
});
